import re
import unicodedata
from bs4 import BeautifulSoup

# ===== NORMALIZACIÓN DE CAMPOS (reutilizable en todo tu pipeline) =====
_NUM = re.compile(r'[\d.,]+')
_ESP = re.compile(r'\s+')

def limpiar_texto(s) -> str:
    """NFC + quita &nbsp; + colapsa whitespace. Aplica M1.4-002 y M1.4-005."""
    s = unicodedata.normalize('NFC', s or '').replace('\xa0', ' ')
    return _ESP.sub(' ', s).strip()

def parsear_precio(txt) -> float | None:
    """'$ 1,250.50 MXN' → 1250.5 | '1.250,50 €' (formato ES) → 1250.5 | 'Gratis' → None"""
    if not txt:
        return None
    limpio = txt.replace(' ', '').replace('\xa0', '')
    m = _NUM.search(limpio)
    if not m:
        return None
    s = m.group()
    # Heurística de formato: la ÚLTIMA coma/punto es el separador decimal
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):     # 1.250,50  (europeo)
            s = s.replace('.', '').replace(',', '.')
        else:                                # 1,250.50  (anglosajón)
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.') if len(s.split(',')[-1]) != 3 else s.replace(',', '')
    try:
        return float(s)
    except ValueError:
        return None

def detectar_moneda(txt) -> str | None:
    for simbolo, codigo in (('$', 'MXN'), ('€', 'EUR'), ('£', 'GBP')):
        if simbolo in (txt or ''):
            return codigo
    return None

# ===== EXTRACTOR TOLERANTE COMPLETO =====
def parsear_items(html):
    soup = BeautifulSoup(html, 'html.parser')
    items, problemas = [], []
    for idx, li in enumerate(soup.select('li.item')):
        link = li.select_one('a.link')
        if link is None:
            problemas.append((idx, 'sin enlace'))
            continue

        precio_el = li.select_one('.price')
        precio_txt = precio_el.get_text(strip=True) if precio_el else ''
        precio = parsear_precio(precio_txt)
        if precio is None and precio_txt:
            problemas.append((idx, f'precio no numerico: {precio_txt!r}'))

        rating_el = li.select_one('.rating')
        rating = None
        if rating_el:
            rm = re.match(r'([\d.]+)\s*/\s*5', rating_el.get_text(strip=True))
            if rm:
                rating = float(rm.group(1))
            else:
                problemas.append((idx, f'rating no numerico: {rating_el.get_text(strip=True)!r}'))

        items.append({
            'url': link.get('href'),
            'nombre': limpiar_texto(link.get_text(' ', strip=True)),
            'precio': precio,
            'moneda': detectar_moneda(precio_txt),
            'rating': rating,
        })
    return items, problemas

# ===== REPORTE DE CALIDAD: lo que separa datos de basura =====
def reporte(items, problemas):
    n = len(items) or 1
    return {
        'extraidos': len(items),
        'con_problemas': len(problemas),
        'tasa_precio_nulo': round(sum(1 for i in items if i['precio'] is None) / n, 3),
        'tasa_rating_nulo': round(sum(1 for i in items if i['rating'] is None) / n, 3),
        'nombres_vacios': sum(1 for i in items if not i['nombre']),
        'detalle_problemas': problemas[:10],
    }

# ===== UMBRAL DE ALARMA =====
# Si tasa_precio_nulo > 0.2 → el markup cambió o tu selector es incorrecto.
# Un scraper sin umbrales llena tu base de NULLs durante semanas sin avisar.

