import time
import hashlib
import pathlib
import urllib.robotparser
import requests

# ===== SCRAPER ÉTICO COMPLETO: robots + rate limit + cache + reanudación =====
class ScraperEtico:
    """Verificado en sandbox: robots y limiter funcionan SIN red."""

    def __init__(self, base_url, user_agent='MiBotEducativo',
                 min_intervalo=1.5, cache_dir='.cache_html', max_paginas=1000):
        self.base = base_url.rstrip('/')
        self.ua = user_agent
        self.min_intervalo = min_intervalo
        self.cache = pathlib.Path(cache_dir)
        self.cache.mkdir(parents=True, exist_ok=True)
        self.max_paginas = max_paginas
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': f'{user_agent}/1.0 (+https://mipwa.example/bot)',
            'Accept-Language': 'es-MX,es;q=0.9',
        })
        self._ultimo = 0.0
        self._robots = None
        self.stats = {'pedidas': 0, 'desde_cache': 0, 'bloqueadas_robots': 0, 'errores': 0}

    # ---- robots.txt ----
    def _cargar_robots(self):
        rp = urllib.robotparser.RobotFileParser()
        try:
            rp.set_url(self.base + '/robots.txt')
            rp.read()
        except Exception:
            rp.parse(['User-agent: *', 'Allow: /'])
        self._robots = rp

    def permitido(self, url) -> bool:
        if self._robots is None:
            self._cargar_robots()
        try:
            return self._robots.can_fetch(self.ua, url)
        except Exception:
            return False      # ante la duda, NO scrapear

    def crawl_delay(self) -> float:
        """Si robots.txt declara Crawl-delay, es el mínimo absoluto a respetar."""
        if self._robots is None:
            self._cargar_robots()
        try:
            d = self._robots.crawl_delay(self.ua)
            return max(self.min_intervalo, float(d)) if d else self.min_intervalo
        except Exception:
            return self.min_intervalo

    # ---- rate limiting ----
    def _esperar(self):
        falta = self.crawl_delay() - (time.monotonic() - self._ultimo)
        if falta > 0:
            time.sleep(falta)
        self._ultimo = time.monotonic()

    # ---- cache en disco: nunca pidas dos veces lo mismo ----
    def _ruta_cache(self, url):
        return self.cache / (hashlib.sha256(url.encode()).hexdigest()[:20] + '.html')

    def get(self, url, usar_cache=True, forzar=False):
        if not self.permitido(url):
            self.stats['bloqueadas_robots'] += 1
            return None
        f = self._ruta_cache(url)
        if usar_cache and f.exists() and not forzar:
            self.stats['desde_cache'] += 1
            return f.read_text(encoding='utf-8')
        self._esperar()
        try:
            r = self.session.get(url, timeout=15)
            if r.status_code == 429:
                espera = int(r.headers.get('Retry-After', 0)) or 60
                time.sleep(min(espera, 120))
                r = self.session.get(url, timeout=15)
            r.raise_for_status()
            r.encoding = r.apparent_encoding or r.encoding
            self.stats['pedidas'] += 1
            f.write_text(r.text, encoding='utf-8')   # cache = reanudación gratis
            return r.text
        except requests.RequestException:
            self.stats['errores'] += 1
            return None

    def close(self):
        self.session.close()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

# ===== LAS 7 REGLAS DEL SCRAPING RESPONSABLE =====
# 1. Lee robots.txt ANTES de empezar. Respétalo aunque sea 'solo una sugerencia'.
# 2. Busca una API oficial o un dump de datos: casi siempre existen y son legales.
# 3. Ritmo humano: >= 1 petición por segundo (o el Crawl-delay declarado).
# 4. Identifícate: User-Agent con nombre, versión y contacto real.
# 5. Cachea: cada byte no pedido es un byte que no molestas.
# 6. Nunca scrapees detrás de login sin permiso explícito (términos de servicio).
# 7. Datos personales: otra liga. GDPR/LFPDPPP aplican. Si hay nombres, emails
#    o teléfonos de personas reales, necesitas base legal, no solo técnica.

# ===== SEÑALES DE QUE ESTÁS MOLESTANDO =====
# 429 frecuentes → baja el ritmo a la mitad
# 403 repentinos → te bloquearon: DETENTE, no cambies de User-Agent para evadirlo
# latencia subiendo (r.elapsed) → el servidor sufre: pausa
# CAPTCHAs → el sitio no quiere bots. Punto. Busca otra fuente.

